const item = $input.first().json;
const headers = item.headers ?? {};
const body = item.body ?? item;
const receivedToken = headers['x-workflow-token'] ?? headers['X-Workflow-Token'];
if (!receivedToken || receivedToken !== $env.N8N_WORKFLOW_TOKEN) {
  throw new Error('Invalid x-workflow-token');
}
if (body.trigger !== 'account.relationship_intelligence_requested') {
  throw new Error(`Unexpected trigger: ${body.trigger ?? 'missing'}`);
}
if (!body.account_id) {
  throw new Error('Missing account_id');
}
if (!body.agent_run_id) {
  throw new Error('Missing agent_run_id');
}
return [{ json: { trigger: body.trigger, account_id: body.account_id, agent_run_id: body.agent_run_id } }];

const context = $input.first().json;
const triggerPayload = $('Validate Trigger').first().json;
const account = context.account ?? {};
const contacts = Array.isArray(context.contacts) ? context.contacts : [];
const timeline = Array.isArray(context.timeline) ? context.timeline : [];
const openSignals = Array.isArray(context.open_signals) ? context.open_signals : [];
const agentRunId = context.agent_run?.id ?? context.agent_run_id ?? triggerPayload.agent_run_id;
const latestTimelineAt = timeline[0]?.occurred_at ?? account.last_activity_at ?? null;
const daysSinceActivity = latestTimelineAt ? Math.floor((Date.now() - Date.parse(latestTimelineAt)) / 86400000) : null;
const hasDecisionMaker = contacts.some((contact) => contact.relationship_role === 'decision_maker');
const hasChampion = contacts.some((contact) => contact.relationship_role === 'champion');
const nextActionFromOpenSignal = openSignals.find((signal) => typeof signal?.suggested_action === 'string' && signal.suggested_action.trim())?.suggested_action ?? null;
const signals = [];
if (!hasDecisionMaker) {
  signals.push({
    signal_type: 'missing_decision_maker',
    severity: 'high',
    title: 'Decision maker missing',
    reason: `${account.name ?? 'This account'} has no mapped decision maker.`,
    suggested_action: 'Identify and add the decision maker before the next commercial step.',
    dedupe_key: 'missing-decision-maker'
  });
}
if (!hasChampion) {
  signals.push({
    signal_type: 'missing_champion',
    severity: 'medium',
    title: 'Champion missing',
    reason: `${account.name ?? 'This account'} has no mapped champion.`,
    suggested_action: 'Find a day-to-day champion who can support the relationship.',
    dedupe_key: 'missing-champion'
  });
}
if (daysSinceActivity === null || daysSinceActivity >= 21) {
  signals.push({
    signal_type: 'stale_touchpoint',
    severity: account.lifecycle_stage === 'active_client' ? 'high' : 'medium',
    title: 'Relationship touchpoint is stale',
    reason: daysSinceActivity === null ? 'No recent account activity is available in workflow context.' : `No recent account activity in ${daysSinceActivity} days.`,
    suggested_action: 'Log a check-in or create a follow-up task.',
    dedupe_key: `stale-touchpoint-${account.lifecycle_stage === 'active_client' ? '21' : '21'}`
  });
}
const fallbackSignals = signals.slice(0, 5);
const fallback = {
  account_id: account.id ?? triggerPayload.account_id,
  agent_run_id: agentRunId,
  output_summary: `Fallback relationship scan found ${fallbackSignals.length} signal${fallbackSignals.length === 1 ? '' : 's'} for ${account.name ?? 'this account'}.`,
  next_action: fallbackSignals[0]?.suggested_action ?? nextActionFromOpenSignal,
  signals: fallbackSignals,
  confidence_score: 0.62,
  model_used: 'deterministic-fallback'
};
const model = $env.OPENROUTER_MODEL || 'anthropic/claude-sonnet-4-6';
const openrouter_request = {
  model,
  messages: [
    { role: 'system', content: 'Return only JSON matching the ClientOps relationship-intelligence writeback contract. Signals must explain why they exist, include a dedupe_key, and stay focused on CRM follow-up.' },
    { role: 'user', content: JSON.stringify({ context, required_fields: ['account_id', 'agent_run_id', 'output_summary', 'next_action', 'signals', 'confidence_score'], signal_schema: { signal_type: 'RelationshipSignalType', severity: 'low|medium|high', title: 'string', reason: 'string', suggested_action: 'string|null', dedupe_key: 'string' } }) }
  ],
  response_format: { type: 'json_object' }
};
return [{ json: { context, fallback, openrouter_request, openrouter_configured: Boolean($env.OPENROUTER_API_KEY) } }];

const prepared = $('Relationship Intelligence').first().json;
const fallback = prepared.fallback;
const response = $input.first()?.json ?? {};

function parsePayload(value) {
  const content = value.choices?.[0]?.message?.content;
  if (typeof content === 'string') {
    try { return JSON.parse(content); } catch (error) { return undefined; }
  }
  return isPlainObject(content) ? content : undefined;
}
function isPlainObject(value) { return value !== null && typeof value === 'object' && !Array.isArray(value); }
function finiteNumber(value, fallbackValue) { const number = typeof value === 'number' ? value : Number(value); return Number.isFinite(number) ? number : fallbackValue; }
function clampNumber(value, fallbackValue, min, max) { return Math.min(max, Math.max(min, finiteNumber(value, fallbackValue))); }
function safeString(value, fallbackValue, maxLength = 1200) { return typeof value === 'string' && value.trim() ? value.trim().slice(0, maxLength) : fallbackValue; }
function safeNullableString(value, fallbackValue, maxLength = 240) {
  if (value === null) return null;
  return safeString(value, fallbackValue, maxLength);
}
function safeChoice(value, allowed, fallbackValue) { return allowed.includes(value) ? value : fallbackValue; }
function safeSignals(value, fallbackValue) {
  if (!Array.isArray(value)) return fallbackValue;
  const signals = [];
  for (const entry of value.slice(0, 10)) {
    if (!isPlainObject(entry)) continue;
    const signalType = safeChoice(entry.signal_type, ['missing_decision_maker', 'missing_champion', 'stale_touchpoint', 'post_event_follow_up_due', 'stale_quote', 'coverage_gap', 'high_risk_engagement', 'negative_sentiment', 'unowned_account', 'cross_sell_opportunity'], null);
    const severity = safeChoice(entry.severity, ['low', 'medium', 'high'], null);
    const title = safeString(entry.title, '', 140);
    const reason = safeString(entry.reason, '', 600);
    const suggestedAction = safeNullableString(entry.suggested_action, null, 240);
    const dedupeKey = safeString(entry.dedupe_key, '', 120);
    if (!signalType || !severity || !title || !reason || !dedupeKey) continue;
    signals.push({ signal_type: signalType, severity, title, reason, suggested_action: suggestedAction, dedupe_key: dedupeKey });
  }
  return signals.length > 0 ? signals : fallbackValue;
}

const parsed = parsePayload(response);
const output = {
  account_id: fallback.account_id,
  agent_run_id: fallback.agent_run_id,
  output_summary: safeString(parsed?.output_summary, fallback.output_summary),
  next_action: safeNullableString(parsed?.next_action, fallback.next_action, 240),
  signals: safeSignals(parsed?.signals, fallback.signals),
  confidence_score: clampNumber(parsed?.confidence_score, fallback.confidence_score, 0, 1),
  model_used: safeString(parsed?.model_used, fallback.model_used, 120),
};
return [{ json: output }];
